 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    tracks = {}
    # Complete each one-cell interruption in a horizontal bar and carry its
    # color upward, with successive bars defining successive vertical sections.
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                tracks.setdefault(c, []).append((r, color))
    for c, bands in tracks.items():
        bands.sort()
        for i, (r, color) in enumerate(bands):
            top = 0 if i == 0 else bands[i - 1][0] + 1
            for rr in range(top, r + 1):
                out[rr][c] = color

    # Matching isolated markers on the bottom edge form short vertical stems.
    bottom_markers = [(c, grid[h - 1][c]) for c in range(w) if grid[h - 1][c] != 0]
    if len(bottom_markers) >= 2 and len({color for _, color in bottom_markers}) == 1:
        for c, color in bottom_markers:
            if all(grid[r][c] == 0 for r in range(h - 3, h - 1)):
                for r in range(h - 3, h):
                    out[r][c] = color
    return out
